fun octets(s: String) = IntArray(s.length / 2) { s.substring(2 * it, 2 * it + 2).toInt(16) }

case("s41-1 offset function", instructionLimit = 1000000) {
  val initial_source =
      octets(
          "",
      )
  for (i in initial_source.indices step 4) setWord(
      "source",
      (0..3).fold(0) { v, j -> v or (initial_source[i + j] shl (8 * j)) },
      i,
  )
  val initial_destination =
      octets(
          "",
      )
  for (i in initial_destination.indices step 4) setWord(
      "destination",
      (0..3).fold(0) { v, j -> v or (initial_destination[i + j] shl (8 * j)) },
      i,
  )
  val initial_state =
      octets(
          "a5a5a5a5a5a5a5a5a5a5a5a5657870616e642033322d62797465206b000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f01000000000000090000004a00000000a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5",
      )
  for (i in initial_state.indices step 4) setWord(
      "state",
      (0..3).fold(0) { v, j -> v or (initial_state[i + j] shl (8 * j)) },
      i,
  )
  val initial_quad =
      octets(
          "a5a5a5a5a5a5a5a511111111a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a504030201a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5436f8d9ba5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a567452301a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5",
      )
  for (i in initial_quad.indices step 4) setWord(
      "quad",
      (0..3).fold(0) { v, j -> v or (initial_quad[i + j] shl (8 * j)) },
      i,
  )
  setWord("mode", 3)
  setWord("in_place", 0)
  setWord("length", 65.toInt())
  setWord("length", 0.toInt(), 4)
  setWord("status", -1)
  val saved = List(9) { 0x456789ab00000000L + it * 509 }
  for (i in 0..7) setRegister("s$i", saved[i])
  setRegister("fp", saved[8])
  setRegister("sp", 0x7fff0000L)
  setRegisterToDataAddress("a0", "state", 12L)
  setRegisterToDataAddress("a1", "source", 3L)
  setRegisterToDataAddress("a2", "destination", 5L)
  setRegister("a3", 65L)
  setRegisterToTextAddress("ra", "function_return")
  startAt("chacha_xor")
  val root = readDataAddress("source")
  val size = (readDataAddress("status") + 4 - root).toInt()
  val before = readBytes("source", size)
  val trace = traceMemoryAccesses(root, size, maxAccesses = 200000)
  val allowedReads: List<Pair<Long, Int>> =
      listOf(
          readDataAddress("state", 12L) to 64,
          readDataAddress("source", 3L) to 65,
          readDataAddress("destination", 5L) to 65,
      )
  val allowedWrites: List<Pair<Long, Int>> = listOf(readDataAddress("destination", 5L) to 65)
  fun fits(a: Long, n: Int, b: Long, s: Int) = a >= b && n <= s && a - b <= s.toLong() - n
  runUntil("function_return")
  expectCondition(
      readBytes("source", 4160)
          .contentEquals(
              octets(
                  "",
              ),
          ),
      "source matches independently modeled phase",
  )
  expectCondition(
      readBytes("destination", 4160)
          .contentEquals(
              octets(
                  "",
              ),
          ),
      "destination matches independently modeled phase",
  )
  expectCondition(
      readBytes("state", 128)
          .contentEquals(
              octets(
                  "a5a5a5a5a5a5a5a5a5a5a5a5657870616e642033322d62797465206b000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f01000000000000090000004a00000000a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5",
              ),
          ),
      "state matches independently modeled phase",
  )
  expectCondition(
      readBytes("quad", 96)
          .contentEquals(
              octets(
                  "a5a5a5a5a5a5a5a511111111a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a504030201a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5436f8d9ba5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a567452301a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5",
              ),
          ),
      "quad matches independently modeled phase",
  )
  expectRegister("v0", 0)
  for (i in 0..7) expectRegister("s$i", saved[i])
  expectRegister("fp", saved[8])
  expectRegister("sp", 0x7fff0000L)
  expectCondition(
      readBytes(2147417920L, 64)
          .contentEquals(
              octets(
                  "657870616e642033322d62797465206b000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f02000000000000090000004a00000000",
              ),
          ),
      "Private state preserves nonce and uses the required local counter",
  )
  expectCondition(
      readBytes(2147417984L, 64)
          .contentEquals(
              octets(
                  "0a88837739d7bf4ef8ccacb0ea2bb9d69d56c394aa351dfda5bf459f0a2e9fe8e721f89255f9c486bf21679c683d4f9c5cf2fa27865526005b06ca374c86af3b",
              ),
          ),
      "Private keystream equals the independent block",
  )
  trace.close()
  for (e in trace.snapshot()) expectCondition(
      (if (e.write) allowedWrites else allowedReads).any { (b, s) ->
        fits(e.address, e.length, b, s)
      },
      "Caller access belongs to a selected readable or writable interval",
  )
  val after = readBytes("source", size)
  for (i in before.indices) if (allowedWrites.none { (b, s) -> fits(root + i, 1, b, s) })
      expectCondition(before[i] == after[i], "Unowned caller bytes remain unchanged")
}

